package wallet

import (
	"errors"
	"fmt"
	"sync"
	"testing"
	"time"
)

// approvalPolicy 构造一条开启大额审批的策略：门槛 10，等待 1 分钟，
// 其余与 validPolicy 一致（单次 30、累计 50、窗口 1 小时）。
func approvalPolicy(c *clock) PolicySpec {
	p := validPolicy(c)
	p.ID = "p-approval"
	p.ApprovalThreshold = 10
	p.ApprovalWait = time.Minute
	return p
